function applyFontScale(value){const scale=value==="large"?"large":value==="compact"?"compact":"normal";document.documentElement.dataset.fontScale=scale;localStorage.setItem("fusaa-font-scale",scale);if($("fontScale"))$("fontScale").value=scale}
function applyReducedMotion(value){const reduced=Boolean(value);document.documentElement.dataset.reduceMotion=String(reduced);localStorage.setItem("fusaa-reduce-motion",String(reduced));if($("reduceMotion"))$("reduceMotion").checked=reduced}
function mountAccessibility(){const main=document.querySelector("main");if(main&&!$("skipContent")){main.id="mainContent";document.body.insertAdjacentHTML("afterbegin",'<a id="skipContent" class="skip-link" href="#mainContent">Aller au contenu</a>')}const settings=$("settings");if(settings&&!$("fontScale"))settings.querySelector(".view-head")?.insertAdjacentHTML("afterend",'<div class="panel accessibility-panel"><h2>Confort de lecture</h2><p class="muted">Ces choix restent enregistrés sur cet appareil.</p><label class="field-label" for="fontScale">TAILLE DU TEXTE</label><select id="fontScale" onchange="applyFontScale(this.value)"><option value="compact">Compacte</option><option value="normal">Normale</option><option value="large">Grande</option></select><label class="muted"><input id="reduceMotion" type="checkbox" style="width:auto" onchange="applyReducedMotion(this.checked)"> Réduire les animations</label></div>');applyFontScale(localStorage.getItem("fusaa-font-scale")||"normal");applyReducedMotion(localStorage.getItem("fusaa-reduce-motion")==="true");document.head.insertAdjacentHTML("beforeend",'<style>.skip-link{position:fixed;z-index:100;left:12px;top:-60px;padding:10px 14px;border-radius:10px;background:#fff;color:#10263a;transition:top .15s}.skip-link:focus{top:12px}:focus-visible{outline:3px solid #5de7d1!important;outline-offset:3px}:root[data-font-scale="large"]{font-size:18px}:root[data-font-scale="compact"]{font-size:14px}:root[data-reduce-motion="true"] *, :root[data-reduce-motion="true"] *::before,:root[data-reduce-motion="true"] *::after{animation-duration:.01ms!important;animation-iteration-count:1!important;scroll-behavior:auto!important;transition-duration:.01ms!important}@media(prefers-reduced-motion:reduce){*,*::before,*::after{scroll-behavior:auto!important;animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}}</style>')}
function mountProgressStyle(){document.head.insertAdjacentHTML("beforeend",'<style>.operation-progress,.print-progress{margin:16px 0;padding:16px;border:1px solid #25d2bb44;border-radius:16px;background:linear-gradient(135deg,#0a2132,#0b1828);box-shadow:0 0 30px #18c9b01c}.operation-head{display:flex;justify-content:space-between;align-items:center;gap:12px}.operation-head b{display:block;font-size:.95rem}.operation-head strong,.operation-head span{color:#35dfc2;font-variant-numeric:tabular-nums}.progress-track{height:9px;margin:13px 0 8px;border-radius:999px;background:#ffffff12;overflow:hidden}.progress-track i{display:block;width:0;height:100%;border-radius:999px;background:linear-gradient(90deg,#18c9b0,#347bf5);box-shadow:0 0 18px #22d9c088;transition:width .45s ease;position:relative}.progress-track i:after{content:"";position:absolute;inset:0;background:linear-gradient(110deg,transparent 20%,#ffffffaa 50%,transparent 80%);animation:progressShine 1.2s linear infinite}.progress-track i.error{background:linear-gradient(90deg,#e25762,#ff9c55);box-shadow:0 0 18px #e2576266}.progress-track i.done{background:linear-gradient(90deg,#25cfa4,#53df88)}@keyframes progressShine{from{transform:translateX(-100%)}to{transform:translateX(100%)}}.operation-progress small{color:#91b3c7}.print-steps{display:grid;grid-template-columns:repeat(5,1fr);gap:5px;margin-top:13px}.print-steps span{padding:7px 4px;text-align:center;border-radius:8px;color:#7893a7;background:#ffffff08;font-size:.68rem;transition:all .3s ease}.print-steps span.done{color:#dffff8;background:#18c9b033;box-shadow:inset 0 -2px #25d2bb}.print-progress{animation:progressPulse 3s ease-in-out infinite}.print-progress .eyebrow{margin-bottom:3px}@keyframes progressPulse{50%{box-shadow:0 0 35px #18c9b02b}}:root[data-theme="light"] .operation-progress,:root[data-theme="light"] .print-progress{background:linear-gradient(135deg,#f4fbfc,#eef5fa);border-color:#8adfd1}:root[data-theme="light"] .print-steps span{color:#668093;background:#dceaf0}:root[data-theme="light"] .print-steps span.done{color:#17675d;background:#c9f0e8}@media(max-width:680px){.print-steps span{font-size:.58rem;padding:6px 2px}.operation-head{align-items:flex-start;flex-direction:column;gap:3px}}</style>')}
function mountJobStyle(){document.head.insertAdjacentHTML("beforeend",'<style>#jobs{display:grid;gap:12px;margin-top:18px}.job-card{position:relative;padding:16px;border:1px solid #ffffff14;border-radius:17px;background:linear-gradient(135deg,#0d2539,#0a1728);overflow:hidden;animation:panelIn .35s ease both}.job-card:before{content:"";position:absolute;inset:0 auto 0 0;width:3px;background:#22d5bd}.job-card.failed:before{background:#ef6570}.job-card.completed:before{background:#55dc8d}.job-card-head{display:flex;justify-content:space-between;align-items:start;gap:10px}.job-card-head h3{margin:7px 0 0;font-size:.96rem;word-break:break-word}.job-card-head strong{color:#41dfc4;font-size:1.1rem}.job-badge{display:inline-block;padding:4px 8px;border-radius:999px;background:#20cdb52b;color:#64ead1;font-size:.66rem;font-weight:800;letter-spacing:.08em;text-transform:uppercase}.failed .job-badge{background:#ef65702b;color:#ff9ca3}.completed .job-badge{background:#55dc8d2b;color:#8bf0ac}.job-mini-track{height:6px;margin:13px 0 7px;background:#ffffff12;border-radius:99px;overflow:hidden}.job-mini-track i{display:block;height:100%;border-radius:99px;background:linear-gradient(90deg,#20cdb5,#347bf5);transition:width .6s ease}.failed .job-mini-track i{background:#ef6570}.completed .job-mini-track i{background:#55dc8d}.job-card-meta{display:flex;justify-content:space-between;color:#8da8ba;font-size:.73rem}.job-error{margin:10px 0;color:#ff9ca3;font-size:.78rem;line-height:1.4}.job-actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:12px}.job-actions button{width:auto;margin:0;padding:7px 10px;font-size:.74rem}.job-card.selected{box-shadow:0 0 0 2px #22d5bd66}@media(max-width:680px){.job-card-head h3{font-size:.86rem}}</style>')}
function paymentLabel(status){return {PAID:"Payé",REJECTED:"Refusé",PENDING:"À confirmer"}[status]||status}
function money(value){return new Intl.NumberFormat("fr-FR",{maximumFractionDigits:0}).format(value||0)+" F CFA"}
function guestOrderParams(){const params=new URLSearchParams(),search=$("guestSearch")?.value.trim(),payment=$("guestPaymentFilter")?.value,status=$("guestStatusFilter")?.value;if(search)params.set("q",search);if(payment)params.set("payment_status",payment);if(status)params.set("job_status",status);if($("guestArchivedFilter")?.checked)params.set("include_archived","true");return params}
async function loadGuestOrders(){const target=$("guestOrdersList");if(!target||!token)return;try{const orders=await api("/api/v1/guest-orders?"+guestOrderParams());target.innerHTML=orders.length?orders.map(order=>{const paid=order.payment_status==="PAID",archived=Boolean(order.archived_at),terminal=["COMPLETED","FAILED","CANCELLED","IGNORED"].includes(order.status);return '<article class="guest-order '+(paid?'paid ':'')+(archived?'archived':'')+'"><div><span class="job-badge">'+esc(archived?'Archivée':paymentLabel(order.payment_status))+'</span><h3>'+esc(order.order_number)+'</h3><p>'+esc(order.document_name)+' · '+esc(order.display_name||"Client")+' · '+esc(order.phone)+'</p><small>'+esc(order.status)+' · '+money(order.estimated_cost)+(order.payment_reference?' · Réf. '+esc(order.payment_reference):'')+(order.invoice_number?' · Reçu '+esc(order.invoice_number):'')+'</small></div><div class="guest-order-actions">'+(!paid&&!archived?'<button class="secondary" onclick="refreshGuestQuote(\''+esc(order.id)+'\')">Actualiser devis</button>':'')+(!archived?'<button class="'+(paid?'secondary':'')+'" onclick="setGuestPayment(\''+esc(order.id)+'\',\''+(paid?'PENDING':'PAID')+'\')">'+(paid?'Retirer validation':'Valider paiement')+'</button>':'')+(paid?'<button class="secondary" onclick="createGuestReceipt(\''+esc(order.id)+'\')">Reçu</button>':'')+(!archived?'<button class="secondary" onclick="openGuestOrderPrint(\''+esc(order.print_job_id)+'\',\''+esc(order.payment_status)+'\')">Impression</button>':'')+(archived?'<button class="secondary" onclick="setGuestArchive(\''+esc(order.id)+'\',false)">Restaurer</button>':terminal?'<button class="secondary" onclick="setGuestArchive(\''+esc(order.id)+'\',true)">Archiver</button>':'')+'</div></article>'}).join(""):'<p class="muted">Aucune commande ne correspond à ces filtres.</p>'}catch(error){target.textContent=error.message}}
async function exportGuestOrders(){try{const response=await fetch("/api/v1/guest-orders/export.csv?"+guestOrderParams(),{headers:{Authorization:"Bearer "+token}});if(!response.ok){let data={};try{data=await response.json()}catch{}throw Error(readableApiError(data.detail))}const url=URL.createObjectURL(await response.blob()),link=document.createElement("a");link.href=url;link.download="fusaa-commandes.csv";link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(error){tell(error.message)}}
const publicPricingFields=["base","per_copy","per_page","monochrome_page","monochrome_discount_from","monochrome_discount_page","color_page","color_discount_from","color_discount_page"];
async function loadPublicPricing(){try{const pricing=await api("/api/v1/public-pricing");publicPricingFields.forEach(field=>{const node=$("publicPrice"+field.replace(/(^|_)([a-z])/g,(_,a,b)=>b.toUpperCase()));if(node)node.value=pricing[field]||0})}catch(error){if($("publicPricingStatus"))$("publicPricingStatus").textContent=error.message}}
async function savePublicPricing(event){event?.preventDefault();try{const pricing={};publicPricingFields.forEach(field=>{const node=$("publicPrice"+field.replace(/(^|_)([a-z])/g,(_,a,b)=>b.toUpperCase()));pricing[field]=Number(node?.value||0)});await api("/api/v1/public-pricing",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(pricing)});$("publicPricingStatus").textContent="Grille tarifaire enregistrée. Actualisez les devis non payés."}catch(error){$("publicPricingStatus").textContent=error.message}}
async function refreshGuestQuote(id){try{await api("/api/v1/guest-orders/"+encodeURIComponent(id)+"/quote",{method:"POST"});tell("Devis actualisé avec le tarif public actuel.");await loadGuestOrders()}catch(error){tell(error.message)}}
async function setGuestArchive(id,archive){if(archive&&!confirm("Archiver cette commande ? Elle restera disponible dans les archives."))return;try{await api("/api/v1/guest-orders/"+encodeURIComponent(id)+(archive?"/archive":"/restore"),{method:"POST"});tell(archive?"Commande archivée.":"Commande restaurée.");await loadGuestOrders();if($("production"))loadProduction()}catch(error){tell(error.message)}}
async function createGuestReceipt(id){try{const receipt=await api("/api/v1/guest-orders/"+encodeURIComponent(id)+"/receipt",{method:"POST"});showReceipt(receipt);await loadGuestOrders()}catch(error){tell(error.message)}}
function showReceipt(receipt){const popup=window.open("","_blank","noopener,noreferrer,width=700,height=760");if(!popup){tell("Autorisez la fenêtre du reçu dans votre navigateur.");return}const safe=value=>esc(value);popup.document.write('<!doctype html><meta charset="utf-8"><title>'+safe(receipt.invoice_number)+'</title><style>body{font-family:Arial,sans-serif;margin:48px;color:#13263a}h1{margin-bottom:4px}.box{margin:28px 0;padding:20px;border:1px solid #ccd7df;border-radius:12px}b{font-size:1.25rem}@media print{button{display:none}}</style><h1>FUSAA INFORMATIQUE</h1><p>Reçu de paiement</p><div class="box"><p><b>'+safe(receipt.invoice_number)+'</b></p><p>Commande : '+safe(receipt.order_number)+'</p><p>Document : '+safe(receipt.document_name)+'</p><p>Montant reçu : <b>'+safe(money(receipt.amount))+'</b></p><p>Référence : '+safe(receipt.payment_reference||"Paiement manuel")+'</p><p>Validé le : '+safe(new Date(receipt.paid_at).toLocaleString("fr-FR"))+'</p></div><button onclick="print()">Imprimer le reçu</button>');popup.document.close()}
async function setGuestPayment(id,status){const reference=status==="PAID"?prompt("Référence de paiement (facultatif) :"):"";if(reference===null)return;try{await api("/api/v1/guest-orders/"+encodeURIComponent(id)+"/payment",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({status,reference})});tell(status==="PAID"?"Paiement validé : la préparation est maintenant autorisée.":"Validation de paiement retirée.");await loadGuestOrders();await refresh()}catch(error){tell(error.message)}}
function openGuestOrderPrint(jobId,paymentStatus){if(paymentStatus!=="PAID"){tell("Validez d’abord le paiement manuel avant de préparer cette impression.");return}selectView("print");$("job").value=jobId;showJob()}
function mountGuestOrders(){document.querySelector("#nav").insertAdjacentHTML("beforeend",'<a href="#publicOrders" data-view="publicOrders">◈ Commandes publiques</a>');document.querySelector("main").insertAdjacentHTML("beforeend",'<section id="publicOrders" class="view"><div class="view-head"><div><p class="eyebrow">VENTES À DISTANCE</p><h1>Commandes publiques</h1><p class="muted">Validez le paiement manuel avant toute préparation ou impression.</p></div><div class="inline-actions"><button class="secondary" onclick="loadGuestOrders()">Actualiser</button><button class="secondary" onclick="exportGuestOrders()">Exporter CSV</button></div></div><div class="panel guest-filters"><input id="guestSearch" placeholder="Rechercher : commande, fichier, client ou téléphone" oninput="loadGuestOrders()"><div class="grid"><select id="guestPaymentFilter" onchange="loadGuestOrders()"><option value="">Tous les paiements</option><option value="PENDING">À confirmer</option><option value="PAID">Payés</option><option value="REJECTED">À revoir</option></select><select id="guestStatusFilter" onchange="loadGuestOrders()"><option value="">Tous les états</option><option value="WAITING_APPROVAL">À préparer</option><option value="READY">Prêt</option><option value="QUEUED">En file</option><option value="PRINTING">Impression</option><option value="COMPLETED">Terminé</option><option value="FAILED">Erreur</option><option value="CANCELLED">Annulé</option></select></div><label class="muted"><input id="guestArchivedFilter" type="checkbox" style="width:auto" onchange="loadGuestOrders()"> Inclure les archives</label></div><form class="panel public-pricing" onsubmit="savePublicPricing(event)"><h2>Tarif public par défaut</h2><p class="muted">Montants en F CFA. Ils servent aux nouveaux devis ; actualisez une commande avant validation de son paiement.</p><div class="grid"><label>Forfait<input id="publicPriceBase" type="number" min="0" value="0"></label><label>Par exemplaire<input id="publicPriceCopy" type="number" min="0" value="0"></label><label>Par page<input id="publicPricePage" type="number" min="0" value="0"></label></div><button type="submit">Enregistrer le tarif</button><p id="publicPricingStatus" class="statusline"></p></form><div id="guestOrdersList" class="guest-orders panel"></div></section>');document.head.insertAdjacentHTML("beforeend",'<style>.guest-orders{display:grid;gap:12px}.guest-filters{margin-bottom:16px}.public-pricing label{font-size:.78rem;color:#adc0d0}.guest-order{display:flex;justify-content:space-between;gap:16px;padding:16px;border:1px solid #ffc45b55;border-radius:16px;background:linear-gradient(135deg,#2e2514,#0d1928)}.guest-order.paid{border-color:#33d9b855;background:linear-gradient(135deg,#102f32,#0d1928)}.guest-order.archived{opacity:.68;border-style:dashed}.guest-order h3{margin:7px 0}.guest-order p,.guest-order small{display:block;margin:5px 0;color:#abc0ce}.guest-order-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.guest-order-actions button{width:auto;margin:0}@media(max-width:680px){.guest-order{flex-direction:column}.guest-order-actions button{flex:1}}</style>')}
async function loadProduction(){const target=$("productionContent");if(!target||!token)return;try{const data=await api("/api/v1/production/dashboard"),summary=data.summary,max=Math.max(1,...data.days.map(day=>Math.max(day.orders,day.completed)));target.innerHTML='<div class="stats">'+card("Commandes publiques",summary.public_orders)+card("Paiements à valider",summary.pending_payment)+card("En production",summary.in_production)+card("Terminés",summary.completed)+card("Erreurs",summary.failed)+card("Encaissement",money(summary.paid_revenue))+'</div><div class="panel"><h2>Activité des 7 derniers jours</h2><div class="production-chart">'+data.days.map(day=>'<div class="production-day"><i style="height:'+Math.max(8,Math.round(day.orders/max*100))+'%"></i><b>'+esc(String(day.orders))+'</b><small>'+esc(day.date.slice(5))+'</small></div>').join("")+'</div><p class="muted">Hauteur = commandes reçues. Les montants encaissés sont comptés après validation manuelle.</p></div><div class="panel"><h2>Dernières commandes publiques</h2><div class="production-list">'+(data.recent_orders.length?data.recent_orders.map(order=>'<button type="button" class="production-row" onclick="selectView(\'publicOrders\')"><span>'+esc(order.order_number)+'</span><b>'+esc(order.document_name)+'</b><small>'+esc(paymentLabel(order.payment_status))+' · '+money(order.estimated_cost)+'</small></button>').join(""):'<p class="muted">Aucune commande publique.</p>')+'</div></div>'}catch(error){target.textContent=error.message}}
