  document.head.insertAdjacentHTML("beforeend",'<style>.shop-link{display:inline-block;padding:10px 14px;border-radius:10px;text-decoration:none;color:#d9edfa}.shop-order,.shop-product{display:flex;align-items:center;justify-content:space-between;gap:12px;border:1px solid #ffffff14;border-radius:12px;padding:12px;margin-top:8px;background:#071827}.shop-order small,.shop-product small{display:block;color:#93abc0;margin-top:4px}.shop-status{min-width:130px}.shop-status select{margin:0}.shop-product b{color:#5be6cf}.shop-stat{width:100%;margin:0;text-align:left;padding:16px;background:linear-gradient(135deg,#10335188,#15263e80);border:1px solid #ffffff10}.shop-stat small{display:block;margin-top:8px;color:#42dfc8;font-weight:800}.shop-glass{width:min(900px,calc(100vw - 28px));max-height:88dvh;overflow:auto;color:#e9f4ff;padding:24px;border:1px solid #65ead38a;border-radius:24px;background:linear-gradient(145deg,#123047f5,#071522f5);box-shadow:0 30px 100px #000a}.shop-glass::backdrop{background:#03101a88;backdrop-filter:blur(8px)}.shop-glass h2{margin:0}.shop-glass .panel{margin-top:15px;background:#08192988}.shop-config-row{display:flex;gap:9px;align-items:center;padding:10px 0;border-bottom:1px solid #ffffff13}.shop-config-row>div:first-child{flex:1}.shop-config-row button{width:auto}.shop-form-actions{display:flex;gap:9px;flex-wrap:wrap}.shop-form-actions button{width:auto}.shop-detail{color:#a6bfce;font-size:.85rem}@media(max-width:600px){.shop-config-row,.shop-order,.shop-product{align-items:flex-start;flex-direction:column}.shop-status{width:100%}}</style>');
