function openShopAssistant(){const dialog=$("shopGlass");$("shopGlassTitle").textContent='Assistant Boutique FUSAA';$("shopGlassBody").innerHTML='<section class="panel"><p class="shop-detail">Je réponds aux questions sur les produits, catégories, stocks, prix et actions de la boutique.</p><label class="field-label">SUJET</label><select id="shopAssistantTopic"><option value="catalogue">Catalogue et produits</option><option value="stock">Stock et ruptures</option><option value="prices">Prix et promotions</option><option value="categories">Catégories</option><option value="actions">Actions à réaliser</option></select><label class="field-label">VOTRE QUESTION</label><textarea id="shopAssistantQuestion" placeholder="Ex. Quels produits sont presque en rupture ?"></textarea><div class="shop-form-actions"><button onclick="askShopAssistant()">Demander à l’assistant</button><button class="secondary" onclick="closeShopGlass()">Fermer</button></div><div id="shopAssistantAnswer" class="notice">Choisissez un sujet ou écrivez votre question.</div></section>';if(!dialog.open)dialog.showModal()}
function askShopAssistant(){const topic=$("shopAssistantTopic").value,question=$("shopAssistantQuestion").value.trim().toLowerCase(),items=shopProductPage.items,low=items.filter(item=>item.enabled&&item.stock_quantity<=3),out=items.filter(item=>item.enabled&&item.stock_quantity===0),categories=shopProductPage.categories;let answer='';if(topic==='stock'||/stock|rupture|manque/.test(question))answer=out.length?'Ruptures sur cette page : '+out.map(item=>item.name).join(', ')+'. Stock faible : '+(low.map(item=>item.name+' ('+item.stock_quantity+')').join(', ')||'aucun')+'.':'Aucune rupture sur cette page. Stock faible : '+(low.map(item=>item.name+' ('+item.stock_quantity+')').join(', ')||'aucun')+'.';else if(topic==='prices'||/prix|promo|reduction/.test(question)){const promos=items.filter(item=>item.original_price_xof);answer=promos.length?'Promotions visibles : '+promos.map(item=>item.name+' à '+shopMoney(item.price_xof)).join(', ')+'. Pour modifier un tarif, ouvrez Configurer sur la carte du produit.':'Aucune promotion sur cette page. Utilisez Prix normal avant réduction dans la fiche produit pour créer une promotion.'}else if(topic==='categories'||/cat.gorie/.test(question))answer=categories.length?'Catégories disponibles : '+categories.filter(item=>item.enabled).map(item=>item.name).join(', ')+'. Vous pouvez les gérer avec le bouton Catégories.':'Aucune catégorie active. Créez-en une depuis le bouton Catégories.';else if(topic==='actions')answer='Actions disponibles : créer un produit, rechercher, filtrer les stocks, configurer une carte, importer une image Cloudinary, archiver un produit et gérer les catégories.';else answer='Cette page affiche '+items.length+' produit(s) sur la page '+shopProductPage.page+'. Utilisez les filtres pour retrouver un article et le bouton Configurer pour changer ses informations.';$("shopAssistantAnswer").textContent=answer}
